export function createVersion(user, git, name, from) {
    git.create(user, name, from);
}
export function changeVersion(user, git, name) {
    git.change(user, name);
}
export function syncVersion(user, git, name) {
    if (git.current().name !== name) {
        throw new Error("The current version doesn't match");
    }
    git.sync(user);
}
export function saveVersion(user, git, name) {
    if (git.current().name !== name) {
        throw new Error("The current version doesn't match");
    }
    git.save(user);
}
export function updateVersion(git, name) {
    if (git.current().name !== name) {
        throw new Error("The current version doesn't match");
    }
    git.update();
}
export function publishVersion(user, git, name) {
    git.publish(user, name);
}
export function deleteVersion(user, git, name) {
    return git.delete(user, name);
}
